//! The view's golden: `build/sb4/view_driver.cpp` (generated by `gen_driver.py`) holds the UNMODIFIED C++ cases the
//! view replaced (`EEScreens.cpp` of round 3, copied verbatim) and the view's two fills (`ee_screenscpp_game_view`,
//! `ee_screenscpp_game_texts`, verbatim) over a stand-in world of the globals and classes they read. Each sample is a
//! random world (missing objects and players among it); the driver prints every group's record (its bytes) and text
//! block as the fills give them, the lobby's slot records, and every moved op's and text's answer by the original
//! case (with the colour ops' calls). The replay answers the view's host from the printed records and asserts every
//! op's and text's answer, and every call, equals the original's (`golden_game_view.txt`: seed 1, 24 samples; a
//! longer trace: `EE_GAME_VIEW_TRACE=<file>` and `--ignored`).

use std::collections::HashMap;

use super::*;

const GOLDEN: &str = include_str!("golden_game_view.txt");

fn unhex(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

/// The view's host over one sample's printed records.
#[derive(Default)]
struct Replay {
    views: HashMap<(u32, u32), EeScreensGameView>,
    texts: HashMap<(u32, u32), Vec<u8>>,
    slots: HashMap<u32, (u32, bool, u32, Vec<u8>)>,
    calls: String,
}

impl ViewHost for Replay {
    fn view(&mut self, group: u32, arg: u32) -> EeScreensGameView {
        *self.views.get(&(group, arg)).unwrap_or_else(|| panic!("no record of group {group} arg {arg}"))
    }
    fn texts(&mut self, group: u32, arg: u32) -> Vec<u8> {
        self.texts.get(&(group, arg)).unwrap_or_else(|| panic!("no texts of group {group} arg {arg}")).clone()
    }
    fn conductor(&mut self, _: usize, _: Sound, _: u32) -> u32 {
        panic!("the sound objects' ops are not in the golden")
    }
    fn sound(&mut self, _: usize, _: Sound, _: u32) -> u32 {
        panic!("the sound objects' ops are not in the golden")
    }
    fn chat_log_count(&mut self) -> u32 {
        panic!("the chat log is not in the golden")
    }
    fn chat_log_text(&mut self, _: u32, _: u32) -> Vec<u8> {
        panic!("the chat log is not in the golden")
    }
    fn form_exists(&mut self, _: u32) -> bool {
        panic!("the forms are not in the golden")
    }
    fn lobby_slot(&mut self, index: u32) -> (u32, bool, u32, Vec<u8>) {
        self.slots[&index].clone()
    }
    fn set_bg_colour(&mut self, control: u32, c: [f32; 3]) {
        let b = |f: f32| f.to_bits();
        self.calls += &format!(" | bg {control} {:08x} {:08x} {:08x}", b(c[0]), b(c[1]), b(c[2]));
    }
    fn set_bar_colour(&mut self, control: u32, c: [f32; 3]) {
        let b = |f: f32| f.to_bits();
        self.calls += &format!(" | bar {control} {:08x} {:08x} {:08x}", b(c[0]), b(c[1]), b(c[2]));
    }
}

/// The replay of a trace; the number of ops and texts checked.
fn replay(trace: &str) -> (usize, usize) {
    let mut h = Replay::default();
    let (mut ops, mut texts) = (0, 0);
    for (n, line) in trace.lines().enumerate() {
        let (head, calls) = line.split_once(" | ").map_or((line, ""), |(a, b)| (a, b));
        let w: Vec<&str> = head.split(' ').collect();
        let num = |i: usize| w[i].parse::<u32>().unwrap();
        match w[0] {
            "sample" => h = Replay::default(),
            "view" => {
                let bytes = unhex(w[3]);
                assert_eq!(bytes.len(), core::mem::size_of::<EeScreensGameView>(), "line {n}: the record's size");
                // SAFETY: a record of the same `repr(C)` layout (the generated header's), its bools 0 or 1
                let v = unsafe { core::ptr::read_unaligned(bytes.as_ptr() as *const EeScreensGameView) };
                h.views.insert((num(1), num(2)), v);
            }
            "texts" => {
                h.texts.insert((num(1), num(2)), unhex(w[3]));
            }
            "slot" => {
                h.slots.insert(num(1), (num(2), num(3) != 0, num(4), unhex(w[5])));
            }
            "op" => {
                h.calls.clear();
                let r = op(&mut h, num(1), num(2), num(3));
                assert_eq!(r, Some(num(4)), "line {n}: {line}");
                let want = if calls.is_empty() { String::new() } else { format!(" | {calls}") };
                assert_eq!(h.calls, want, "line {n}: {line}");
                ops += 1;
            }
            "text" => {
                assert_eq!(text(&mut h, num(1), num(2)), Some(unhex(w[3])), "line {n}: {line}");
                texts += 1;
            }
            _ => panic!("line {n}: {line}"),
        }
    }
    (ops, texts)
}

#[test]
fn golden_replay() {
    let (ops, texts) = replay(GOLDEN);
    assert!(ops > 1000 && texts > 1000, "{ops} ops, {texts} texts");
}

#[test]
#[ignore]
fn golden_trace() {
    let path = std::env::var("EE_GAME_VIEW_TRACE").expect("EE_GAME_VIEW_TRACE");
    let (ops, texts) = replay(&std::fs::read_to_string(path).unwrap());
    eprintln!("{ops} ops, {texts} texts");
}
